/**
 * Per-member project mutes: which projects a member has silenced in an org.
 */
import { and, eq, inArray } from "drizzle-orm";
import { getDb, projectMutes } from "@/server/db";
import { brandId } from "./_mappers";
import { orgPredicate } from "./base-repository";
import type { IsoTimestamp, OrgId, ProjectId, UserId } from "@/types/common";

/** Idempotent: muting an already-muted project leaves the original row alone. */
export async function insertMute(
  orgId: OrgId,
  userId: UserId,
  projectId: ProjectId,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .insert(projectMutes)
    .values({ orgId, userId, projectId, mutedAt: at })
    .onConflictDoNothing()
    .run();
}

export async function deleteMute(
  orgId: OrgId,
  userId: UserId,
  projectId: ProjectId,
): Promise<void> {
  getDb()
    .delete(projectMutes)
    .where(
      and(
        orgPredicate(projectMutes.orgId, orgId),
        eq(projectMutes.userId, userId),
        eq(projectMutes.projectId, projectId),
      ),
    )
    .run();
}

export async function listMutedProjectIds(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ProjectId[]> {
  const rows = getDb()
    .select({ projectId: projectMutes.projectId })
    .from(projectMutes)
    .where(
      and(
        orgPredicate(projectMutes.orgId, orgId),
        eq(projectMutes.userId, userId),
      ),
    )
    .all();

  return rows.map((row) => brandId<ProjectId>(row.projectId));
}

/** Which of `userIds` have muted `projectId` — the fan-out's one lookup per event. */
export async function listMutedUserIds(
  orgId: OrgId,
  projectId: ProjectId,
  userIds: readonly UserId[],
): Promise<readonly UserId[]> {
  if (userIds.length === 0) return [];

  const rows = getDb()
    .select({ userId: projectMutes.userId })
    .from(projectMutes)
    .where(
      and(
        orgPredicate(projectMutes.orgId, orgId),
        eq(projectMutes.projectId, projectId),
        inArray(projectMutes.userId, [...userIds]),
      ),
    )
    .all();

  return rows.map((row) => brandId<UserId>(row.userId));
}

