  title: string;
  body: string;
  href: string;
  actorId: UserId | null;
};

/** Channels used when a recipient has never touched their preferences. */
const DEFAULT_CHANNELS: readonly NotificationChannel[] = ["in_app", "email"];

/**
 * Writes one notification row per recipient, each with the channel set that
 * recipient's preferences allow. A recipient who has muted every channel is
 * skipped entirely rather than given a row nobody will ever see.
 */
export async function notify(
  orgId: OrgId,
  kind: NotificationKind,
  recipients: readonly UserId[],
  payload: NotificationPayload,
): Promise<readonly Notification[]> {
  if (recipients.length === 0) return [];

  const org = await orgRepo.findOrgById(orgId);
  const flags: FlagContext = {
    orgId,
    userId: payload.actorId,
    plan: org?.plan ?? "free",
    role: null,
    overrides: org?.settings.enabledFlagOverrides,
  };

  const rows = [];

  for (const recipientId of new Set(recipients)) {
    if (recipientId === payload.actorId) continue;

    const preference = await preferenceRepo.getPreference(
      orgId,
      recipientId,
      kind,
    );
    const channels = resolveChannels(preference, flags);
    if (channels.length === 0) continue;

    rows.push({
      orgId,
      recipientId,
      kind,
      title: payload.title,
      body: payload.body,
      href: payload.href,
      actorId: payload.actorId,
      channels,
    });
  }
''', '''export type NotificationPayload = {
  title: string;
  body: string;
  href: string;
  actorId: UserId | null;
  /** The project the notification is about; mutes are applied per recipient when set. */
  projectId?: ProjectId | null;
};

/** Channels used when a recipient has never touched their preferences. */
const DEFAULT_CHANNELS: readonly NotificationChannel[] = ["in_app", "email"];

/**
 * Kinds addressed to one recipient personally. A muted project still reaches
 * its recipient through these, just never by email; every other kind about a
 * muted project is dropped for that recipient.
 */
const PERSONAL_KINDS: ReadonlySet<NotificationKind> = new Set<NotificationKind>([
  "issue_assigned",
  "comment_mention",
  "issue_overdue",
]);

/**
 * Writes one notification row per recipient, each with the channel set that
 * recipient's preferences allow. A recipient who has muted every channel is
 * skipped entirely rather than given a row nobody will ever see. When the
 * payload names a project, a recipient who muted it gets only the personal
 * kinds, and those without email.
 */
export async function notify(
  orgId: OrgId,
  kind: NotificationKind,
  recipients: readonly UserId[],
  payload: NotificationPayload,
): Promise<readonly Notification[]> {
  if (recipients.length === 0) return [];

  const org = await orgRepo.findOrgById(orgId);
  const flags: FlagContext = {
    orgId,
    userId: payload.actorId,
    plan: org?.plan ?? "free",
    role: null,
    overrides: org?.settings.enabledFlagOverrides,
  };

  const projectId = payload.projectId ?? null;
  const uniqueRecipients = [...new Set(recipients)];
  const muted = new Set(
    projectId === null
      ? []
      : await projectMuteRepo.listMutedUserIds(orgId, projectId, uniqueRecipients),
  );

  const rows = [];

  for (const recipientId of uniqueRecipients) {
    if (recipientId === payload.actorId) continue;

    const isMuted = muted.has(recipientId);
    if (isMuted && !PERSONAL_KINDS.has(kind)) continue;

    const preference = await preferenceRepo.getPreference(
      orgId,
      recipientId,
      kind,
    );
    const channels = resolveChannels(preference, flags).filter(
      (channel) => !isMuted || channel !== "email",
    );
    if (channels.length === 0) continue;

    rows.push({
      orgId,
      recipientId,
      kind,
      title: payload.title,
      body: payload.body,
      href: payload.href,
      actorId: payload.actorId,
      projectId,
      channels,
    });
  }
''')

