): Promise<void> {
  assertOrgScope(actor, orgId);
  const project = await findReadableProject(actor, orgId, projectId);
  await projectMuteRepo.deleteMute(orgId, actor.userId, project.id);
}

/** The projects the actor has muted in one org. Only their own mutes are visible. */
export async function listMutedProjectIds(
  actor: Actor,
